-- Narrow, idempotent onboarding transitions; no plaintext recovery data is accepted.
create or replace function public.complete_profile(new_display_name text, new_bio text) returns void language plpgsql security definer set search_path=public as $$ begin perform require_authenticated(); if char_length(coalesce(new_display_name,''))>80 or char_length(coalesce(new_bio,''))>500 then raise exception 'Invalid profile'; end if; perform set_config('app.onboarding_rpc','1',true); update profiles set display_name=nullif(trim(new_display_name),''),bio=nullif(trim(new_bio),''),profile_completed_at=coalesce(profile_completed_at,now()) where id=auth.uid(); end $$;
create or replace function public.handle_country() returns void language plpgsql security definer set search_path=public as $$ begin perform require_authenticated(); perform set_config('app.onboarding_rpc','1',true); update profiles set country_handled_at=coalesce(country_handled_at,now()) where id=auth.uid(); end $$;
create or replace function public.set_onboarding_interests(selected_slugs text[]) returns void language plpgsql security definer set search_path=public as $$ begin perform require_authenticated(); if exists(select 1 from unnest(selected_slugs) s where s not in ('cybersecurity','linux','programming','ai','ctf','science','hardware')) then raise exception 'Invalid interest'; end if; insert into user_interests(user_id,interest_room_id) select auth.uid(),r.id from rooms r where r.kind='interest' and r.slug=any(selected_slugs) on conflict do nothing; insert into room_members(room_id,user_id,role) select r.id,auth.uid(),'member' from rooms r where r.kind='interest' and r.slug=any(selected_slugs) on conflict do nothing; perform set_config('app.onboarding_rpc','1',true); insert into room_members(room_id,user_id,role) select id,auth.uid(),'member' from rooms where kind='world' on conflict do nothing; update profiles set interests_handled_at=coalesce(interests_handled_at,now()) where id=auth.uid(); end $$;
revoke all on function public.complete_profile(text,text),public.handle_country(),public.set_onboarding_interests(text[]) from public; grant execute on function public.complete_profile(text,text),public.handle_country(),public.set_onboarding_interests(text[]) to authenticated;
